import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.CnJ-JtFX.js";const m=JSON.parse('{"title":"EP.07 设计器不是画布，是五层各司其职","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.07-lowcode-engine-architecture.md","filePath":"comics/EP.07-lowcode-engine-architecture.md","lastUpdated":1792683644000}'),r={name:"comics/EP.07-lowcode-engine-architecture.md"};function n(s,e,c,l,d,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="ep-07-设计器不是画布-是五层各司其职" tabindex="-1">EP.07 设计器不是画布，是五层各司其职 <a class="header-anchor" href="#ep-07-设计器不是画布-是五层各司其职" aria-label="Permalink to &quot;EP.07 设计器不是画布，是五层各司其职&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/07-lowcode-engine-architecture">guide/07-lowcode-engine-architecture</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君把拖拽、渲染、属性面板写进同一个 <code>Editor.tsx</code>，第一版能跑；等他加撤销、加协作、加自定义物料时，发现每个需求都要改内核。</li><li><strong>揭秘</strong>：码叔把设计器拆成五层——engine 管生命周期，designer 管节点树与选中态，simulator 用 iframe 做真实渲染，material 管组件元数据，plugins 承载平台业务。</li><li><strong>实证</strong>：像素酱按「先注册插件，再 <code>init</code>」的顺序启动引擎，先 <code>setAssets</code> 再 <code>importSchema</code>，画布第一次渲染就没有报错。</li><li><strong>结案</strong>：码叔让三栏闭环跑通——大纲能选中节点，画布能渲染订单卡片，右栏能改「卡片标题」。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-一个组件为什么会长成内核" tabindex="-1">第一格：一个组件为什么会长成内核 <a class="header-anchor" href="#第一格-一个组件为什么会长成内核" aria-label="Permalink to &quot;第一格：一个组件为什么会长成内核&quot;">​</a></h3><p>把画布、属性面板、拖拽逻辑写在一个组件里，短期是最省事的写法。问题出现在第二次需求变更：撤销需要记录节点历史，协作需要感知选中态，自定义物料需要一份组件描述。三件事都指向同一份运行时状态，而这份状态被锁在组件内部，外部只能通过回调去改。</p><p>漫画里的代码芯片不是反面教材，而是很多低代码原型的真实起点。它的问题不是「代码丑」，而是没有边界：渲染、状态、扩展点混在一起，任何新能力都只能往内核里塞。低代码引擎的第一课，就是把这份状态拆出去，让每一层只暴露必要的接口。</p><p>对应正文：<a href="./../guide/07-lowcode-engine-architecture#原理拆解">原理拆解</a>。</p><h3 id="第二格-五层各自管什么" tabindex="-1">第二格：五层各自管什么 <a class="header-anchor" href="#第二格-五层各自管什么" aria-label="Permalink to &quot;第二格：五层各自管什么&quot;">​</a></h3><ul><li><strong>engine</strong>：启动、插件注册、<code>init</code> 生命周期，以及全局配置。</li><li><strong>designer</strong>：节点树、选中态、拖拽、撤销栈，是编辑行为的核心。</li><li><strong>simulator</strong>：把 schema 渲染进 iframe，保证编辑态与运行态隔离。</li><li><strong>material</strong>：组件元数据、Setter、资源包，决定「有哪些组件可用」。</li><li><strong>plugins</strong>：平台自己的业务能力，例如保存、预览、出码、权限。</li></ul><p>依赖方向是单向的：plugins 依赖 engine 提供的上下文，engine 调用 designer 与 simulator，designer 读取 material。反过来让 material 去依赖 plugins，或者让 simulator 直接改 designer 的节点树，都会让边界失效。边界一旦失效，后面每加一个功能都要先猜「这段逻辑到底该放哪」。</p><h3 id="第三格-启动顺序为什么重要" tabindex="-1">第三格：启动顺序为什么重要 <a class="header-anchor" href="#第三格-启动顺序为什么重要" aria-label="Permalink to &quot;第三格：启动顺序为什么重要&quot;">​</a></h3><p>引擎的启动可以概括为三步：注册插件、初始化插件、调用 <code>engine.init(container)</code>。插件在 <code>init()</code> 里做的事情，通常包括设置 scenario、注入物料、导入初始 schema、往骨架里加面板。</p><p>顺序不能随意调换。<code>setAssets</code> 必须在 <code>importSchema</code> 之前，因为导入 schema 时引擎要按 <code>componentsMap</code> 解析组件；如果物料还没注册，画布会先报「不是 React 组件」。同理，业务插件如果依赖初始化插件写入的 schema，就要在 <code>meta.dependencies</code> 里声明依赖，让引擎按拓扑顺序初始化。</p><h3 id="第四格-最小闭环的三栏" tabindex="-1">第四格：最小闭环的三栏 <a class="header-anchor" href="#第四格-最小闭环的三栏" aria-label="Permalink to &quot;第四格：最小闭环的三栏&quot;">​</a></h3><p>判断一个设计器是否真的跑起来，不看它有多少按钮，而看三栏是否对得上：</p><ol><li><strong>大纲</strong>能列出 <code>Page → Card → Input/Button</code> 的层级；</li><li><strong>画布</strong>能渲染出真实组件，而不是一行占位文字；</li><li><strong>设置器</strong>在选中 Card 后出现「卡片标题」这类属性。</li></ol><p>只要这三栏能联动，后面接物料、接插件、接保存才有意义。漫画最后一格用 <code>componentsMap</code> 与 <code>componentsTree</code> 做收尾：前者回答「组件从哪来」，后者回答「页面长什么样」，缺一个都跑不通。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>把 UMD 脚本顺序当无关紧要</strong>：React、ReactDOM、PropTypes、Next、engine-core、engine-ext 的顺序错了，页面只会白屏。</li><li><strong>先 <code>importSchema</code> 再 <code>setAssets</code></strong>：画布会报组件不存在，因为解析 schema 时还没有物料。</li><li><strong>把组件元数据塞进 <code>packages[].components</code></strong>：引擎只读顶层 <code>components</code>，放错层级会报 <code>Cannot read properties of undefined</code>。</li><li><strong>在同一个页面重复 <code>engine.init</code></strong>：一个页面只能有一个引擎实例，切换章节应整页刷新。</li><li><strong>直接改 <code>node_modules</code> 里的 CSS</strong>：样式应通过主题包或覆盖层处理，改依赖会在下次安装时丢失。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. engine、designer、simulator 三层的职责边界是什么？</b></summary><p>engine 负责启动、插件注册与全局生命周期；designer 负责节点树、选中态、拖拽与撤销等编辑行为；simulator 负责把 schema 渲染进 iframe，隔离编辑态与运行态。三者通过引擎上下文通信，而不是互相直接引用。</p></details><details><summary><b>2. 为什么必须先 `setAssets` 再 `importSchema`？</b></summary><p><code>importSchema</code> 会按 <code>componentsMap</code> 解析每个节点对应的真实组件。如果物料尚未注册，解析不到组件，画布就会报「不是 React 组件」。所以物料注入必须发生在 schema 导入之前。</p></details><details><summary><b>3. 三栏闭环具体指哪三栏，如何验证？</b></summary><p>大纲、画布、设置器。验证方式是：大纲里能看到 <code>Page → Card → Input/Button</code>；画布上能渲染出真实卡片与按钮；选中 Card 后右栏出现「卡片标题」等属性。三栏能互相联动，才算设计器真正跑通。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/07-lowcode-engine-architecture">第 07 章正文</a></li><li><a href="./../guide/08-lowcode-engine-materials">第 08 章 · 物料协议</a></li><li><a href="./../appendix/glossary">术语表</a></li></ul>',27)])])}const p=o(r,[["render",n]]);export{m as __pageData,p as default};
